    mapOf("id" to "4", "name" to "Animal Friend", "desc" to "At the first rank of this perk, animals simply won't attack. At the second rank, they will actually come to your aid in combat, but never against another animal.", "icon" to R.drawable.perk_animal_friend.toString()),
