    mapOf("id" to "6", "name" to "Better Criticals", "desc" to "With the Better Criticals perk, you gain a 50% damage bonus every time a critical hit is scored on an opponent.", "icon" to R.drawable.perk_better_criticals.toString()),
    mapOf("id" to "7", "name" to "Better Healing", "desc" to "While Arcade is a companion, the player regains more health from all sources.", "icon" to R.drawable.perk_better_healing.toString()),
