    mapOf("id" to "14", "name" to "Chem Resistant", "desc" to "Having the Chem Resistant perk means you're 50% less likely to develop an addiction to chems, like Psycho or Jet.", "icon" to R.drawable.perk_chem_resistant.toString()),
    mapOf("id" to "15", "name" to "Cherchez La Femme", "desc" to "In combat, you do +10% damage against female opponents. Outside of combat, you'll sometimes have access to unique dialogue options when dealing with the same sex.", "icon" to R.drawable.perk_cherchez_la_femme.toString()),
