    mapOf("id" to "17", "name" to "Commando", "desc" to "While using a rifle (or similar two-handed weapon), your accuracy in V.A.T.S. is significantly increased.", "icon" to R.drawable.perk_commando.toString()),
    mapOf("id" to "18", "name" to "Comprehension", "desc" to "With the Comprehension perk, you gain one additional skill point whenever a skill book is read.", "icon" to R.drawable.perk_comprehension.toString()),
    mapOf("id" to "19", "name" to "Concentrated Fire", "desc" to "With Concentrated Fire, your accuracy to hit any body part in V.A.T.S. increases slightly with each subsequent hit on that body part.", "icon" to R.drawable.perk_concentrated_fire.toString()),
    mapOf("id" to "20", "name" to "Confirmed Bachelor", "desc" to "In combat, you do +10% damage against male opponents. Outside of combat, you'll sometimes have access to unique dialogue options when dealing with the same sex.", "icon" to R.drawable.perk_confirmed_bachelor.toString()),
    mapOf("id" to "21", "name" to "Contract Killer", "desc" to "Once you have the Contract Killer perk, any good character you kill will have an ear on their corpse. This ear can then be sold to a certain person (whose identity is disclosed when you take the perk) for caps and negative Karma.", "icon" to R.drawable.perk_contract_killer.toString()),
    mapOf("id" to "22", "name" to "Cowboy", "desc" to "You do 25% more damage when using any revolver, lever-action firearm, dynamite, knife, or hatchet.", "icon" to R.drawable.perk_cowboy.toString()),
    mapOf("id" to "23", "name" to "Cyborg", "desc" to "You've made permanent enhancements to your body! The Cyborg perk instantly adds +10% to your Damage, Poison, and Radiation Resistances, and 10 points to the Energy Weapons skill.", "icon" to R.drawable.perk_cyborg.toString()),
    mapOf("id" to "24", "name" to "Demolition Expert", "desc" to "With each rank of this perk, all of your explosive weapons do an additional 20% damage.", "icon" to R.drawable.perk_demolition_expert.toString()),
    mapOf("id" to "25", "name" to "Dream Crusher", "desc" to "Something about your presence dampens others' desires to exceed. Any enemy's chance of getting critical hits on you is reduced by 50%.", "icon" to R.drawable.perk_dream_crusher.toString()),
    mapOf("id" to "26", "name" to "Educated", "desc" to "With the Educated perk, you gain two more skill points every time you advance in level. This perk is best taken early on, to maximize its effectiveness.", "icon" to R.drawable.perk_educated.toString()),
    mapOf("id" to "27", "name" to "Empathy Synthesizer", "desc" to "Your prefrontal cortex has been enhanced with the Empathy Synthesizer, increasing your Charisma by 1.", "icon" to R.drawable.perk_empathy_synthesizer.toString()),
    mapOf("id" to "28", "name" to "Enhanced Sensors", "desc" to "While ED-E is a companion, the player can detect enemies at an increased range. Additionally, enemies will appear on the player's compass and can be targeted in V.A.T.S. even when cloaked.", "icon" to R.drawable.perk_enhanced_sensors.toString()),
    mapOf("id" to "29", "name" to "Entomologist", "desc" to "With the Entomologist perk, you do an additional +50% damage every time you attack a mutated insect, like the radroach, giant ant, or radscorpion.", "icon" to R.drawable.perk_entomologist.toString()),
    mapOf("id" to "30", "name" to "Explorer", "desc" to "When you choose the Explorer perk, every location in the world is revealed on your map. So get out there and explore!", "icon" to R.drawable.perk_explorer.toString()),
