    mapOf("id" to "34", "name" to "Finesse", "desc" to "With the Finesse perk, you have a higher chance to score a critical hit on an opponent in combat, equivalent to 5 extra points of Luck.", "icon" to R.drawable.perk_finesse.toString()),
    mapOf("id" to "35", "name" to "Fortune Finder", "desc" to "With the Fortune Finder perk, you'll find considerably more Nuka-Cola caps in containers than you normally would.", "icon" to R.drawable.perk_fortune_finder.toString()),
    mapOf("id" to "36", "name" to "Four Eyes", "desc" to "While wearing any type of glasses, you have +1 PER. Without glasses, you have -1 PER.", "icon" to R.drawable.perk_four_eyes.toString()),
