    mapOf("id" to "38", "name" to "Full Maintenance", "desc" to "While Raul is a companion, the Condition of weapons and armor decays 75% slower.", "icon" to R.drawable.perk_full_maintenance.toString()),
    mapOf("id" to "39", "name" to "Ghastly Scavenger", "desc" to "With Ghastly Scavenger, when you're in Sneak mode, you gain the option to eat a Super Mutant or Feral Ghoul corpse to regain Health. Every time you feed, you lose Karma, and if the act is witnessed, it is considered a crime against nature.", "icon" to R.drawable.perk_ghastly_scavenger.toString()),
    mapOf("id" to "40", "name" to "Good Natured", "desc" to "You're Good Natured at heart, more prone to solving problems with your mind than violence. You gain +5 to Barter, Medicine, Repair, Science, and Speech, but have -5 to Energy Weapons, Explosives, Guns, Melee Weapons, and Unarmed.", "icon" to R.drawable.perk_good_natured.toString()),
    mapOf("id" to "41", "name" to "Grim Reaper's Sprint", "desc" to "If you kill a target while in V.A.T.S., all of your Action Points are restored upon exiting V.A.T.S.", "icon" to R.drawable.perk_grim_reaper.toString()),
