    mapOf("id" to "44", "name" to "Hand Loader", "desc" to "You know your way around a reloading bench and don't let good brass and hulls go to waste. When you use Guns, you are more likely to recover cases and hulls. You also have all hand load recipes unlocked at any of the wasteland's reloading benches.", "icon" to R.drawable.perk_hand_loader.toString()),
