    mapOf("id" to "47", "name" to "Hit the Deck", "desc" to "Your extensive familiarity with Explosives allows you to ignore a portion of their damage. Your Damage Threshold is increased by 25 against any and all Explosives -- even your own.", "icon" to R.drawable.perk_hit_the_deck.toString()),
