    mapOf("id" to "58", "name" to "Lady Killer", "desc" to "In combat, you do +10% damage against female opponents. Outside of combat, you'll sometimes have access to unique dialogue options when dealing with the opposite sex.", "icon" to R.drawable.perk_lady_killer.toString()),
