    mapOf("id" to "86", "name" to "NEMEAN Sub-Dermal Armor", "desc" to "Your skin has been toughened by the NEMEAN Sub-Dermal Armor, increasing your total Damage Threshold by 4.", "icon" to R.drawable.perk_nemean_sub_dermal_armor.toString()),
