    mapOf("id" to "88", "name" to "Night Person", "desc" to "When the sun is down, a Night Person gains +2 to both Intelligence and Perception (up to a maximum of 10). This perk directly affects your 'internal clock' and remains active both inside and outside.", "icon" to R.drawable.perk_night_person.toString()),
    mapOf("id" to "89", "name" to "Ninja", "desc" to "The Ninja perk grants you the power of the fabled shadow warriors. When attacking, you gain a +15% critical chance on all Melee and Unarmed attacks. Additionally, Sneak attack criticals do 25% more damage than normal.", "icon" to R.drawable.perk_ninja.toString()),
    mapOf("id" to "90", "name" to "Nociception Regulator Endurance Implant", "desc" to "Your nervous system has been enhanced with the Nociception Regulator, increasing your Endurance by 1.", "icon" to R.drawable.perk_nociception_regulator.toString()),
