    mapOf("id" to "94", "name" to "PHOENIX Monocyte Breeder", "desc" to "Your regenerative ability has been enhanced by the PHOENIX Monocyte Breeder implant, causing you to slowly regenerate lost hit points.", "icon" to R.drawable.perk_phoenix_monocyte_breeder.toString()),
