    mapOf("id" to "96", "name" to "Plasma Spaz", "desc" to "You're just so excited about plasma that you can't (magnetically) contain yourself! The AP costs for all plasma weapons (including Plasma Grenades) are reduced by 20%.", "icon" to R.drawable.perk_plasma_spaz.toString()),
    mapOf("id" to "97", "name" to "Probability Calculator Luck Implant", "desc" to "Your frontal lobe has been enhanced with the Probability Calculator, increasing your Luck by 1.", "icon" to R.drawable.perk_probability_calculator.toString()),
    mapOf("id" to "98", "name" to "Purifier", "desc" to "As a purifier of the wasteland, you do +50% damage with Melee and Unarmed weapons against Centaurs, Nightstalkers, Spore Plants, Spore Carriers, Deathclaws, Super Mutants, and Feral Ghouls.", "icon" to R.drawable.perk_purifier.toString()),
    mapOf("id" to "99", "name" to "Pyromaniac", "desc" to "With the Pyromaniac perk, you do +50% damage with fire-based weapons, like the Flamer and Shishkebab.", "icon" to R.drawable.perk_pyromaniac.toString()),
