    mapOf("id" to "106", "name" to "Reflex Booster Agility Implant", "desc" to "Your central nervous node has been enhanced with the Reflex Booster, increasing your Agility by 1.", "icon" to R.drawable.perk_reflex_booster.toString()),
    mapOf("id" to "107", "name" to "Regular Maintenance", "desc" to "While Raul is a companion, the Condition of weapons and armor decays more slowly.", "icon" to R.drawable.perk_regular_maintenance.toString()),
    mapOf("id" to "108", "name" to "Retention", "desc" to "With the Retention perk, the bonuses granted by skill magazines last three times as long.", "icon" to R.drawable.perk_retention.toString()),
