    mapOf("id" to "110", "name" to "Run 'n Gun", "desc" to "The Run 'n Gun perk reduces accuracy penalties with one-handed Guns and Energy Weapons while walking or running.", "icon" to R.drawable.perk_run_n_gun.toString()),
