    mapOf("id" to "112", "name" to "Scribe Assistant", "desc" to "While Veronica is a companion, the player can craft Workbench items through Veronica's dialogue.", "icon" to R.drawable.perk_scribe_assistant.toString()),
    mapOf("id" to "113", "name" to "Scribe Counter", "desc" to "Scribes in the Brotherhood of Steel are often not well-trained in the combat use of the high-tech gear employed by Paladins. They rely on unarmed defensive moves like the Scribe Counter to keep enemies at bay. Perform a standard attack out of a block hit reaction to execute a Scribe Counter.", "icon" to R.drawable.perk_scribe_counter.toString()),
    mapOf("id" to "114", "name" to "Scrounger", "desc" to "With the Scrounger perk, you'll find considerably more ammunition in containers than you normally would.", "icon" to R.drawable.perk_scrounger.toString()),
    mapOf("id" to "115", "name" to "Search and Mark", "desc" to "While Rex is a companion, unequipped chems, firearms, and ammunition within a short distance are highlighted when you zoom the camera.", "icon" to R.drawable.perk_search_and_mark.toString()),
    mapOf("id" to "116", "name" to "Shotgun Surgeon", "desc" to "With this perk, your precision with a scattergun is something to behold. When using shotguns, regardless of ammunition used, you ignore an additional 10 points of a target's Damage Threshold.", "icon" to R.drawable.perk_shotgun_surgeon.toString()),
    mapOf("id" to "117", "name" to "Silent Running", "desc" to "With the Silent Running perk, running no longer factors into a successful sneak attempt.", "icon" to R.drawable.perk_silent_running.toString()),
    mapOf("id" to "118", "name" to "Size Matters", "desc" to "You are obsessed with really big weapons. With each rank of this perk, you gain an additional 15 points to the Big Guns skill.", "icon" to R.drawable.perk_size_matters.toString()),
    mapOf("id" to "119", "name" to "Slayer", "desc" to "The slayer walks the earth! The speed of all Melee Weapons and Unarmed attacks is increased by 30%.", "icon" to R.drawable.perk_slayer.toString()),
    mapOf("id" to "120", "name" to "Small Frame", "desc" to "Due to your small size, you have +1 Agility but your limbs are more easily crippled (25% extra limb damage).", "icon" to R.drawable.perk_small_frame.toString()),
    mapOf("id" to "121", "name" to "Sniper", "desc" to "With the Sniper perk, your chance to hit an opponent's head in V.A.T.S. is significantly increased.", "icon" to R.drawable.perk_sniper.toString()),
    mapOf("id" to "122", "name" to "Solar Powered", "desc" to "With the Solar Powered perk, you gain an additional 2 points to Strength when in direct sunlight, and slowly regenerate lost Health.", "icon" to R.drawable.perk_solar_powered.toString()),
    mapOf("id" to "123", "name" to "Splash Damage", "desc" to "When you're deep in enemy territory, you just start chucking grenades and hope for the best. All Explosives have a 25% larger area of effect when they detonate.", "icon" to R.drawable.perk_splash_damage.toString()),
    mapOf("id" to "124", "name" to "Spotter", "desc" to "While Boone is a companion, hostile targets are highlighted whenever the player is actively aiming.", "icon" to R.drawable.perk_spotting.toString()),
    mapOf("id" to "125", "name" to "Spray and Pray", "desc" to "Your attacks do much less damage to companions, allowing you to liberally spray an area with reckless abandon.", "icon" to R.drawable.perk_spray_and_pray.toString()),
    mapOf("id" to "126", "name" to "Stealth Girl", "desc" to "While Lily is a companion, the duration of Stealth Boys is increased by 200% and all Sneak Attack Critical Hits do an additional 10% damage.", "icon" to R.drawable.perk_stealth_girl.toString()),
    mapOf("id" to "127", "name" to "Stonewall", "desc" to "You gain +5 Damage Threshold against all Melee Weapons and Unarmed attacks and cannot be knocked down in combat.", "icon" to R.drawable.perk_stonewall.toString()),
    mapOf("id" to "128", "name" to "Strong Back", "desc" to "With this perk, you can carry an additional 50 lbs. of equipment.", "icon" to R.drawable.perk_strong_back.toString()),
    mapOf("id" to "129", "name" to "Super Slam!", "desc" to "All Melee Weapons (except thrown) and Unarmed attacks have a chance of knocking your target down.", "icon" to R.drawable.perk_super_slam.toString()),
    mapOf("id" to "130", "name" to "Survivalist", "desc" to "You are a master of the outdoors. This Perk confers the ability to survive in hostile environments. You get a +20% bonus to Outdoorsman for survival purposes, for each level of this Perk.", "icon" to R.drawable.perk_survivalist.toString()),
    mapOf("id" to "131", "name" to "Survival Assistant", "desc" to "+2% Poison and Radiation Resistance, +5 HP, +2 Medicine, +2 Science, +2% DR, +2 Sneak, +2 Speech, +1% Critical Chance", "icon" to R.drawable.perk_survival_assistant.toString()),
    mapOf("id" to "132", "name" to "Survival Expert", "desc" to "+4% Poison and Radiation Resistance, +10 HP, +4 Medicine, +4 Science, +4% DR, +4 Sneak, +4 Speech, +2% Critical Chance", "icon" to R.drawable.perk_survival_expert.toString()),
    mapOf("id" to "133", "name" to "Survival Guru", "desc" to "+6% Poison and Radiation Resistance, +15 HP, +6 Medicine, +6 Science, +6% DR, +6 Sneak, +6 Speech, +3% Critical Chance", "icon" to R.drawable.perk_survival_guru.toString()),
    mapOf("id" to "134", "name" to "Swift Learner", "desc" to "With each level of Swift Learner your character will gain an additional +10% to experience whenever Experience Points are earned.", "icon" to R.drawable.perk_swift_learner.toString()),
    mapOf("id" to "135", "name" to "Tag!", "desc" to "The Tag! perk allows you to select a fourth skill to be a Tag skill, which instantly raises it by fifteen points.", "icon" to R.drawable.perk_tag.toString()),
    mapOf("id" to "136", "name" to "Terrifying Presence", "desc" to "In some conversations, you gain the ability to initiate combat while terrifying a mob of opponents, sending them fleeing away for safety.", "icon" to R.drawable.perk_terrifying_presence.toString()),
    mapOf("id" to "137", "name" to "The Professional", "desc" to "Up close and personal, that's how you like it. Your Sneak Attack Criticals with pistols, revolvers, and submachine guns, whether Guns or Energy Weapons, all inflict an additional 20% damage.", "icon" to R.drawable.perk_the_professional.toString()),
    mapOf("id" to "138", "name" to "Thief", "desc" to "With each rank of Thief perk, you gain an immediate bonus of 5 points to both the Sneak and Lockpick skills.", "icon" to R.drawable.perk_thief.toString()),
    mapOf("id" to "139", "name" to "Toughness", "desc" to "With the Toughness perk, you gain +3 to overall Damage Threshold. This perk may be taken twice, with the second rank granting an additional +3.", "icon" to R.drawable.perk_toughness.toString()),
    mapOf("id" to "140", "name" to "Travel Light", "desc" to "While wearing light armor or no armor, you run 10% faster.", "icon" to R.drawable.perk_travel_light.toString()),
    mapOf("id" to "141", "name" to "Trigger Discipline", "desc" to "While using Guns and Energy Weapons, you fire 20% more slowly but are 20% more accurate.", "icon" to R.drawable.perk_trigger_discipline.toString()),
    mapOf("id" to "142", "name" to "Unstoppable Force", "desc" to "Your martial might is truly legendary. You do a large amount of additional damage through enemy blocks with all Melee Weapons and Unarmed attacks.", "icon" to R.drawable.perk_unstoppable_force.toString()),
    mapOf("id" to "143", "name" to "Vigilant Recycler", "desc" to "Waste not, want not. When you use Energy Weapons, you are more likely to recover drained ammunition. You also have more efficient recycling recipes available at the wasteland's workbenches.", "icon" to R.drawable.perk_vigilant_recycler.toString()),
    mapOf("id" to "144", "name" to "Weapon Handling", "desc" to "Weapon Strength Requirements are now 2 points lower than normal for you.", "icon" to R.drawable.perk_weapon_handling.toString()),
    mapOf("id" to "145", "name" to "Whiskey Rose", "desc" to "While Cass is a companion, she and the player gain Damage Threshold when they drink Whiskey. Additionally, the player does not suffer intelligence loss from consuming alcohol and ignores the negative effects of alcohol addiction.", "icon" to R.drawable.perk_whiskey_rose.toString()),
    mapOf("id" to "146", "name" to "Wild Wasteland", "desc" to "Wild Wasteland unleashes the most bizarre and silly elements of post-apocalyptic America. Not for the faint of heart or the serious of temperament.", "icon" to R.drawable.perk_wild_wasteland.toString())
)

